from itertools import product
def se_entao(p, q):
    return (not p) or q
for p, q in product([True, False], repeat=2):
    print(p, q, se_entao(p, q))

from itertools import product
def se_entao(p, q):
    return (not p) or q
def equivalentes(f, g):
    return all(f(p, q) == g(p, q) for p, q in product([True, False], repeat=2))
print(equivalentes(se_entao, lambda p, q: se_entao(not q, not p)))
print(equivalentes(se_entao, lambda p, q: se_entao(q, p)))
